+				__( 'Core icon collection manifest is empty or invalid.', 'gutenberg' )
+			);
+			return;
+		}
+
+		foreach ( $collection as $icon_name => $icon_data ) {
+			if (
+				empty( $icon_data['filePath'] )
+				|| ! is_string( $icon_data['filePath'] )
