+<?php
+/**
+ * Content Guidelines REST API Controller.
+ *
+ * Specialized controller for the site-wide "content" guideline singleton.
+ * Exposes a flat `/wp/v2/content-guidelines` endpoint that always reads,
+ * creates, and updates a single post tagged with the `content` term in
+ * the `wp_guideline_type` taxonomy. Other guideline posts (artifacts) are
+ * served by the standard `/wp/v2/guidelines` collection.
+ *
+ * @package gutenberg
+ */
+
+if ( ! defined( 'ABSPATH' ) ) {
+	exit;
+}
+
+/**
+ * REST API controller for the site-wide content guidelines singleton.
+ */
+class Gutenberg_Content_Guidelines_REST_Controller extends WP_REST_Posts_Controller {
+
+	/**
+	 * Maximum length for guideline text strings.
+	 *
+	 * @var int
+	 */
+	const MAX_GUIDELINE_LENGTH = 5000;
+
+	/**
+	 * Maximum length for category label strings.
+	 *
+	 * @var int
+	 */
+	const MAX_LABEL_LENGTH = 200;
+
+	/**
+	 * REST base for the singleton route.
+	 *
+	 * @var string
+	 */
+	const REST_BASE = 'content-guidelines';
+
+	/**
+	 * Constructor.
+	 */
+	public function __construct() {
+		parent::__construct( Gutenberg_Guidelines_Post_Type::POST_TYPE );
+		$this->rest_base = self::REST_BASE;
+	}
+
+	/**
+	 * Resolves a post ID to a content-typed guideline post.
+	 *
+	 * Restricts /wp/v2/content-guidelines/{id} to posts tagged with the
+	 * `content` term. Other guideline types are addressable only via the
+	 * standard /wp/v2/guidelines collection.
+	 *
+	 * @param int $id Post ID.
+	 * @return WP_Post|WP_Error Post object on success, WP_Error on failure.
+	 */
+	protected function get_post( $id ) {
+		$post = parent::get_post( $id );
+		if ( is_wp_error( $post ) ) {
+			return $post;
+		}
+
+		if ( ! Gutenberg_Guidelines_Post_Type::is_content_guideline( $post->ID ) ) {
+			return new WP_Error(
+				'rest_post_invalid_id',
+				__( 'Invalid post ID.', 'gutenberg' ),
+				array( 'status' => 404 )
+			);
+		}
+
+		return $post;
+	}
+
+	/**
+	 * Registers the routes for the content guidelines singleton.
+	 *
+	 * Calls parent to register standard /{id} CRUD routes, then overrides the
+	 * collection route with a singleton GET endpoint.
+	 */
+	public function register_routes() {
+		parent::register_routes();
+
+		// Override collection route with singleton GET + create.
+		register_rest_route(
+			$this->namespace,
+			'/' . $this->rest_base,
+			array(
+				array(
+					'methods'             => WP_REST_Server::READABLE,
+					'callback'            => array( $this, 'get_guidelines' ),
+					'permission_callback' => array( $this, 'get_guidelines_permissions_check' ),
+					'args'                => array(
+						'category' => array(
+							'description'       => __( 'Limit response to a specific guideline category.', 'gutenberg' ),
+							'type'              => 'string',
+							'enum'              => Gutenberg_Guidelines_Post_Type::VALID_CATEGORIES,
+							'sanitize_callback' => 'sanitize_text_field',
+						),
+						'block'    => array(
+							'description'       => __( 'Limit response to guidelines for a specific block type.', 'gutenberg' ),
+							'type'              => 'string',
+							'sanitize_callback' => 'sanitize_text_field',
+						),
+						'status'   => array(
+							'description'       => __( 'Limit response to guidelines with a specific status.', 'gutenberg' ),
+							'type'              => 'string',
+							'enum'              => Gutenberg_Guidelines_Post_Type::VALID_STATUSES,
+							'sanitize_callback' => 'sanitize_text_field',
+						),
+					),
+				),
+				array(
+					'methods'             => WP_REST_Server::CREATABLE,
+					'callback'            => array( $this, 'create_item' ),
+					'permission_callback' => array( $this, 'create_item_permissions_check' ),
+					'args'                => $this->get_endpoint_args_for_item_schema( WP_REST_Server::CREATABLE ),
+				),
+				'schema' => array( $this, 'get_public_item_schema' ),
+			),
+			true
+		);
+	}
+
+	/**
+	 * Retrieves the query params for the collection.
+	 *
+	 * Overridden to return empty since we use a singleton pattern, not a collection.
+	 *
+	 * @return array Empty collection parameters.
+	 */
+	public function get_collection_params() {
+		return array();
+	}
+
+	/**
+	 * Checks if a given request has access to read the singleton guidelines.
+	 *
+	 * @param WP_REST_Request $request Full details about the request.
+	 * @return true|WP_Error True if the request has read access, WP_Error object otherwise.
+	 */
+	public function get_guidelines_permissions_check( WP_REST_Request $request ) { // phpcs:ignore VariableAnalysis.CodeAnalysis.VariableAnalysis.UnusedVariable
+		$post_type = get_post_type_object( $this->post_type );
+		if ( ! current_user_can( $post_type->cap->read ) ) {
+			return new WP_Error(
+				'rest_forbidden',
+				__( 'Sorry, you are not allowed to view the guidelines.', 'gutenberg' ),
+				array( 'status' => rest_authorization_required_code() )
+			);
+		}
+
+		return true;
+	}
+
+	/**
+	 * Restricts guideline creation to administrators.
+	 *
+	 * Defers to the parent controller for per-post checks (status validation,
+	 * sticky support, etc.) once the admin gate passes.
+	 *
+	 * @param WP_REST_Request $request Full details about the request.
+	 * @return true|WP_Error True if the request has access, WP_Error object otherwise.
+	 */
+	public function create_item_permissions_check( $request ) {
+		if ( ! current_user_can( 'manage_options' ) ) {
+			return new WP_Error(
+				'rest_cannot_create',
+				__( 'Sorry, you are not allowed to create guidelines.', 'gutenberg' ),
+				array( 'status' => rest_authorization_required_code() )
+			);
+		}
+
+		return parent::create_item_permissions_check( $request );
+	}
+
+	/**
+	 * Restricts guideline updates to administrators.
+	 *
+	 * @param WP_REST_Request $request Full details about the request.
+	 * @return true|WP_Error True if the request has access, WP_Error object otherwise.
+	 */
+	public function update_item_permissions_check( $request ) {
+		if ( ! current_user_can( 'manage_options' ) ) {
+			return new WP_Error(
+				'rest_cannot_edit',
+				__( 'Sorry, you are not allowed to edit guidelines.', 'gutenberg' ),
+				array( 'status' => rest_authorization_required_code() )
+			);
+		}
+
+		return parent::update_item_permissions_check( $request );
+	}
+
+	/**
+	 * Restricts guideline deletion to administrators.
+	 *
+	 * @param WP_REST_Request $request Full details about the request.
+	 * @return true|WP_Error True if the request has access, WP_Error object otherwise.
+	 */
+	public function delete_item_permissions_check( $request ) {
+		if ( ! current_user_can( 'manage_options' ) ) {
+			return new WP_Error(
+				'rest_cannot_delete',
+				__( 'Sorry, you are not allowed to delete guidelines.', 'gutenberg' ),
+				array( 'status' => rest_authorization_required_code() )
+			);
+		}
+
+		return parent::delete_item_permissions_check( $request );
+	}
+
+	/**
+	 * Gets the singleton guidelines.
+	 *
+	 * Supports query parameters:
+	 * - ?status=publish|draft - Filter by status
+	 * - ?category=copy|images|site|blocks|additional - Return only specific category
+	 * - ?block=core/paragraph - Return only specific block's guidelines
+	 *
+	 * @param WP_REST_Request $request Full details about the request.
+	 * @return WP_REST_Response Response object.
+	 */
+	public function get_guidelines( WP_REST_Request $request ) {
+		$status_filter = $request->get_param( 'status' );
+		$post          = $this->get_guidelines_post( $status_filter );
+
+		if ( ! $post ) {
+			$empty_status = $status_filter ? $status_filter : 'draft';
+			return rest_ensure_response(
+				array(
+					'id'                   => 0,
+					'status'               => $empty_status,
+					'guideline_categories' => new stdClass(),
+				)
+			);
+		}
+
+		return $this->prepare_item_for_response( $post, $request );
+	}
+
+	/**
+	 * Creates the content guidelines singleton.
+	 *
+	 * Enforces the singleton constraint — only one post tagged with the
+	 * `content` term may exist.
+	 *
+	 * @param WP_REST_Request $request Full details about the request.
+	 * @return WP_REST_Response|WP_Error Response object on success, or WP_Error on failure.
+	 */
+	public function create_item( $request ) {
+		$existing = $this->get_guidelines_post();
+		if ( $existing ) {
+			return new WP_Error(
+				'rest_guidelines_exists',
+				__( 'Guidelines already exist. Use PATCH to update.', 'gutenberg' ),
+				array( 'status' => 400 )
+			);
+		}
+
+		$content_term_id = self::get_or_create_term_id(
+			Gutenberg_Guidelines_Post_Type::TERM_CONTENT,
+			__( 'Content', 'gutenberg' )
+		);
+		if ( is_wp_error( $content_term_id ) ) {
+			return $content_term_id;
+		}
+
+		$prepared             = $this->prepare_item_for_database( $request );
+		$prepared->post_type  = $this->post_type;
+		$prepared->post_title = __( 'Guidelines', 'gutenberg' );
+		$prepared->tax_input  = array(
+			Gutenberg_Guidelines_Post_Type::TAXONOMY => array( $content_term_id ),
+		);
+
+		if ( ! isset( $prepared->post_status ) ) {
+			$prepared->post_status = 'draft';
+		}
+
+		$post_id = wp_insert_post( wp_slash( (array) $prepared ), true );
+
+		if ( is_wp_error( $post_id ) ) {
+			return $post_id;
+		}
+
+		if ( isset( $request['guideline_categories'] ) ) {
+			$categories = $this->sanitize_guideline_categories( $request['guideline_categories'] );
+			$this->save_guideline_categories_to_meta( $post_id, $categories );
+		}
+
+		$post = get_post( $post_id );
+
+		$request->set_param( 'context', 'edit' );
+		$response = $this->prepare_item_for_response( $post, $request );
+		$response = rest_ensure_response( $response );
+		$response->set_status( 201 );
+		$response->header( 'Location', rest_url( sprintf( '%s/%s/%d', $this->namespace, $this->rest_base, $post_id ) ) );
+
+		return $response;
+	}
+
+	/**
+	 * Updates the content guidelines singleton.
+	 *
+	 * Saves guideline categories to meta before updating the post so that
+	 * the revision captures the updated meta values.
+	 *
+	 * @param WP_REST_Request $request Full details about the request.
+	 * @return WP_REST_Response|WP_Error Response object on success, or WP_Error on failure.
+	 */
