+
+			const headings = screen.getAllByRole( 'heading', { level: 1 } );
+			expect( headings ).toHaveLength( 1 );
+			expect( headings[ 0 ] ).toHaveTextContent( 'General' );
+		} );
+
+		it( 'should render a single item without `to` as an h1', () => {
