+ * @param predicate  Function that determines if the item should stay
+ *                   in the array.
+ * @return Filtered array.
+ */
+function filterWithReference< T >(
+	collection: T[],
+	predicate: ( item: T ) => boolean
+): T[] {
+	const filteredCollection = collection.filter( predicate );
