+ * @return Transformed object.
+ */
+const mapValues = < T, U >(
+	obj: Partial< Record< string, T > >,
+	callback: ( value: T ) => U
+): Partial< Record< string, U > > =>
+	Object.entries( obj ).reduce( ( acc, [ key, value ] ) => {
+		if ( value === undefined ) {
+			return acc;
+		}
+		return {
+			...acc,
+			[ key ]: callback( value ),
+		};
+	}, {} );
