+ */
+function isValidAnnotationRange( annotation: {
+	range?: AnnotationRange | null;
+} ): boolean {
+	return Boolean(
+		annotation.range &&
+			typeof annotation.range.start === 'number' &&
+			typeof annotation.range.end === 'number' &&
+			annotation.range.start <= annotation.range.end
+	);
