+			configurable: true,
+		} );
+
+		// Re-import the module to trigger the side effects
+		jest.isolateModules( () => {
+			require( '../cross-origin-isolation' );
+		} );
+
+		expect( observeSpy ).not.toHaveBeenCalled();
+	} );
+
