+			id: 1,
+			sizeSlug: 'large',
+		} );
+		const secondImage = createBlock( 'core/image', {
+			url: 'https://example.com/two.jpg',
+			alt: 'Two',
+			id: 2,
+			sizeSlug: 'large',
+		} );
