+const __experimentalLabel = ( attributes, { context } ) => {
+	if ( context === 'list-view' ) {
+		return attributes?.label;
+	}
+
+	if ( context === 'appender' ) {
+		const type = attributes?.type || 'link';
+		return sprintf(
+			/* translators: %s: block type (e.g., 'page', 'post', 'category') */
+			_x( 'Add %s', 'add default block type' ),
