+	if ( domNode.nodeType === domNode.TEXT_NODE ) {
+		return domNode.nodeValue!;
+	}
+
+	if ( domNode.nodeType !== domNode.ELEMENT_NODE ) {
+		throw new TypeError(
+			'A block node can only be created from a node of type text or ' +
+				'element.'
+		);
+	}
