+	deprecated( 'wp.blocks.node.toHTML', {
+		since: '6.1',
+		version: '6.3',
+		alternative: 'wp.richText.toHTMLString',
+		link: 'https://developer.wordpress.org/block-editor/how-to-guides/block-tutorial/introducing-attributes-and-editable-fields/',
