+/**
+ * Internal dependencies
+ */
+import { getSibling } from './utils';
+
+/**
+ * Removes trailing br elements from text-level content.
+ *
+ * @param node Node to check.
+ */
+export default function brRemover( node: Node ): void {
+	if ( node.nodeName !== 'BR' ) {
+		return;
+	}
+
+	if ( getSibling( node, 'next' ) ) {
+		return;
+	}
+
