+/**
+ * WordPress dependencies
+ */
+import { isEmpty, isPhrasingContent } from '@wordpress/dom';
+
+export default function normaliseBlocks(
+	HTML: string,
+	options: Record< string, unknown > = {}
+): string {
+	const decuDoc = document.implementation.createHTMLDocument( '' );
+	const accuDoc = document.implementation.createHTMLDocument( '' );
+
+	const decu = decuDoc.body;
+	const accu = accuDoc.body;
+
+	decu.innerHTML = HTML;
+
+	while ( decu.firstChild ) {
+		const node = decu.firstChild;
+
+		// Text nodes: wrap in a paragraph, or append to previous.
+		if ( node.nodeType === node.TEXT_NODE ) {
+			if ( isEmpty( node as Element ) ) {
+				decu.removeChild( node );
+			} else {
+				if ( ! accu.lastChild || accu.lastChild.nodeName !== 'P' ) {
+					accu.appendChild( accuDoc.createElement( 'P' ) );
+				}
+
+				accu.lastChild!.appendChild( node );
+			}
+			// Element nodes.
+		} else if ( node.nodeType === node.ELEMENT_NODE ) {
+			// BR nodes: create a new paragraph on double, or append to previous.
+			if ( node.nodeName === 'BR' ) {
+				if ( node.nextSibling && node.nextSibling.nodeName === 'BR' ) {
+					accu.appendChild( accuDoc.createElement( 'P' ) );
+					decu.removeChild( node.nextSibling );
+				}
+
+				// Don't append to an empty paragraph.
+				if (
+					accu.lastChild &&
+					accu.lastChild.nodeName === 'P' &&
+					accu.lastChild.hasChildNodes()
+				) {
+					accu.lastChild.appendChild( node );
+				} else {
+					decu.removeChild( node );
+				}
+			} else if ( node.nodeName === 'P' ) {
+				// Only append non-empty paragraph nodes.
+				if ( isEmpty( node as Element ) && ! options.raw ) {
+					decu.removeChild( node );
+				} else {
+					accu.appendChild( node );
+				}
+			} else if ( isPhrasingContent( node as Element ) ) {
+				if ( ! accu.lastChild || accu.lastChild.nodeName !== 'P' ) {
+					accu.appendChild( accuDoc.createElement( 'P' ) );
+				}
+				accu.lastChild!.appendChild( node );
+			} else {
+				accu.appendChild( node );
+			}
+		} else {
+			decu.removeChild( node );
+		}
+	}
+
+	return accu.innerHTML;
+}

