+	const allowedFields = [
+		'apiVersion',
+		'title',
+		'category',
+		'parent',
+		'ancestor',
+		'icon',
+		'description',
+		'keywords',
+		'attributes',
+		'providesContext',
+		'usesContext',
+		'selectors',
+		'supports',
+		'styles',
+		'example',
+		'variations',
+		'blockHooks',
+		'allowedBlocks',
+	];
