+		return sprintf(
+			/* translators: accessibility text. 1: The block title. 2: The block row number. */
+			__( '%1$s Block. Row %2$d' ),
+			title,
+			position
+		);
+	} else if ( hasPosition && direction === 'horizontal' ) {
