+					stylePropertyMap[ styleName ].support![ 0 ] in supports &&
+					getValueFromObjectPath(
+						supports,
+						stylePropertyMap[ styleName ].support!
+					) !== false
+				) {
+					supportKeys.push( styleName );
+					return;
+				}
+			}
