+			getAutocompleteMatch( '', completers, defaultOptions )
+		).toBeNull();
+	} );
+
+	it( 'should return null when no completers are provided', () => {
+		expect(
+			getAutocompleteMatch( 'some text /', [], defaultOptions )
+		).toBeNull();
+	} );
