+											7;
+										nextFocusable = subDays(
+											day,
+											daysToSubtract
+										);
+									}
+									if ( event.key === 'End' ) {
+										const dayOfWeek = day.getDay();
+										const daysToAdd =
+											( weekStartsOn + 6 - dayOfWeek ) %
+											7;
+										nextFocusable = addDays(
+											day,
+											daysToAdd
+										);
+									}
