+											! isSameMonth(
+												nextFocusable,
+												viewing
+											)
+										) {
+											setViewing( nextFocusable );
+											onMonthPreviewed?.(
+												dateI18n(
+													TIMEZONELESS_FORMAT,
+													nextFocusable,
+													-nextFocusable.getTimezoneOffset()
+												)
+											);
+										}
+									}
+								} }
+							/>
+						);
+					} )
+				) }
+			</Calendar>
+		</Wrapper>
+	);
