+}: ConnectorItemProps ) {
+	const headingId = useId();
+	return (
+		<Item className={ className }>
+			<VStack spacing={ 4 } role="group" aria-labelledby={ headingId }>
+				<HStack alignment="center" spacing={ 4 } wrap>
+					{ logo }
+					<FlexBlock>
+						<VStack spacing={ 0 }>
