+): Field< ContentType > {
+	const field: Field< ContentType > = {
+		id,
+		label,
+		type: 'text',
+		placeholder: options.placeholder,
+		description: options.description,
+		getValue: ( { item } ) =>
+			( item.config.labels as Record< string, any > )[ id ] ?? '',
+		setValue: ( { item, value } ) =>
+			( {
