+			<Stack direction="column" gap="md">
+				<Text variant="body-md">{ helpText }</Text>
+				<Stack direction="row" justify="flex-end" gap="sm">
+					<Button
+						__next40pxDefaultSize
+						variant="secondary"
+						size="compact"
+						accessibleWhenDisabled
+						disabled={ ! canAutoFill }
+						onClick={ () =>
