+					</Button>
+					<Button
+						__next40pxDefaultSize
+						size="compact"
+						icon={ trash }
+						isDestructive
+						label={ __( 'Clear labels' ) }
+						accessibleWhenDisabled
+						disabled={ ! hasOverrides }
+						onClick={ () => {
+							const cleared: Record<
+								string,
+								string | undefined
+							> = {
+								singular_name: data.config.labels.singular_name,
+							};
