+
+async function serializeAndSaveCRDTDoc( objectType, objectId, room ) {
+	const serializedDoc = await getSyncManager()?.createPersistedCRDTDoc(
+		objectType,
+		objectId
+	);
+
+	if ( ! serializedDoc ) {
+		return;
+	}
+
+	await apiFetch( {
+		path: SYNC_SAVE_API_PATH,
+		method: 'POST',
+		data: {
+			room,
+			doc: serializedDoc,
+		},
+	} );
+}
